using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Object=UnityEngine.Object;
public static class ValidateTreeAndGrainOptimization {
 static long Tris(Renderer[] rs)=>rs.OfType<MeshRenderer>().Sum(r=>(long)r.GetComponent<MeshFilter>().sharedMesh.triangles.Length/3);
 public static string Trees(){var root=GameObject.Find("New_Map").transform;var hills=root.Find("12_Farmyards_and_boundaries/Low poly hill groves");var ordinary=root.GetComponentsInChildren<LODGroup>().Where(l=>l.name.Contains("Tree")).ToArray();var report=new List<string>();bool good=true;foreach(var l in hills.GetComponentsInChildren<LODGroup>()){var levels=l.GetLODs();if(levels.Length!=3||levels.Any(x=>x.renderers.Any(r=>!r)))good=false;foreach(var level in levels)foreach(var r in level.renderers)if(r.sharedMaterials.Length!=r.GetComponent<MeshFilter>().sharedMesh.subMeshCount||r.sharedMaterials.Any(m=>!m||!m.shader.isSupported))good=false;}report.Add((good?"PASS ":"FAIL ")+"227 grove cells have valid complete 3D LODs and material slots");report.Add((ordinary.Length==340&&ordinary.All(l=>l.GetLODs().Length==4&&Tris(l.GetLODs()[0].renderers)<=5000&&Tris(l.GetLODs()[3].renderers)<=600)?"PASS ":"FAIL ")+"340 individual trees retain fuller 3D near models and 3D far models");var sample=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/NewMap/FiveHangars/HillTrees/Hill grove 267.asset");report.Add((sample.triangles.Length/3>40&&sample.triangles.Length/3<9904?"PASS ":"FAIL ")+"User-highlighted grove uses moderate 3D detail below its original 9904 triangles");report.Add("Hill highest-detail total="+hills.GetComponentsInChildren<LODGroup>().Sum(l=>Tris(l.GetLODs()[0].renderers))+"; individual highest-detail total="+ordinary.Sum(l=>Tris(l.GetLODs()[0].renderers)));var result=string.Join("\n",report);File.WriteAllText("output/TreeOptimization/validation.txt",result);return result;}
 public static string Grain(){if(!Application.isPlaying)throw new Exception("Play mode required");var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var states=Object.FindObjectsByType<HangarGrainVisibility>(FindObjectsSortMode.None).Where(s=>s.gameObject.scene==scene).OrderBy(s=>s.name).ToArray();var report=new List<string>();bool pass=states.Length==5;int active=Object.FindObjectsByType<GrainPile>(FindObjectsSortMode.None).Count(p=>p.gameObject.scene==scene);report.Add((active==1?"PASS ":"FAIL ")+"Only starter grain simulation active on startup");pass&=active==1;
 foreach(var state in states){bool open=state.HangarOpen;bool correct=state.GrainRoot&&state.GrainRoot.activeInHierarchy==open;report.Add((correct?"PASS ":"FAIL ")+state.name+" grain matches opened="+open);pass&=correct;if(open)continue;
 try{state.SetHangarOpen(true);var pile=state.GrainRoot.GetComponent<GrainPile>();var kernels=state.GrainRoot.GetComponent<CornSurfaceKernels>();bool initialized=state.GrainRoot.activeInHierarchy&&pile.isActiveAndEnabled&&pile.Kilograms>0&&kernels.KernelCount>0;report.Add((initialized?"PASS ":"FAIL ")+state.name+" grain and kernels initialize when opened");pass&=initialized;state.SetHangarOpen(false);bool off=!state.GrainRoot.activeInHierarchy&&!pile.isActiveAndEnabled&&!kernels.isActiveAndEnabled;report.Add((off?"PASS ":"FAIL ")+state.name+" whole grain object deactivates when closed");pass&=off;}
 finally{state.SetHangarOpen(open);}}
 report.Add((pass?"PASS ":"FAIL ")+"All grain visibility checks; original opened/closed states restored");var result=string.Join("\n",report);File.WriteAllText("output/TreeOptimization/grain-validation.txt",result);return result;}
}

